<?php
namespace App\Http\Controllers;
use App\Models\{StagingAcceptanceRun as Run,StagingAcceptanceCheck as Check,StagingAcceptanceIssue as Issue,User};
use App\Support\{AcceptanceSource,StagingAcceptance as Acceptance,LearningAccess};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;

class StagingAcceptanceController extends Controller {
 private function manager(Request $r):void {abort_unless(Acceptance::allowed($r->user()),403);}
 private function privateView(string $view,array $data=[]) {return response()->view('acceptance.'.$view,$data)->header('Cache-Control','no-store, private')->header('Referrer-Policy','no-referrer');}
 private function details(Request $r):array {
  $d=$r->validate(['title'=>['required','string','max:160'],'target'=>['required','string','max:200'],'reference'=>['required','string','max:300'],'programmes'=>['required','string','max:2000'],'exclusions'=>['required','string','max:2000'],'live_messaging'=>['nullable','boolean'],'confirmed'=>['accepted']]);return [...collect($d)->only(['title','target','reference','programmes','exclusions'])->all(),'live_messaging'=>$r->boolean('live_messaging')];
 }
 public function index(Request $r) {
  $this->manager($r);$r->validate(['page'=>['nullable','integer','min:1']]);$source=app(AcceptanceSource::class)->capture();$runs=Run::orderByDesc('created_at')->orderByDesc('id')->paginate(15);$positions=[];$titles=[];
  foreach($runs as$run){$positions[$run->id]=Acceptance::position($run,$source);try{$titles[$run->id]=$run->details['title'];}catch(\Throwable){$titles[$run->id]='Run evidence needs checking';}}
  return $this->privateView('index',compact('source','runs','positions','titles'));
 }
 public function create(Request $r) {$this->manager($r);$run=Acceptance::create($r->user(),(int)$r->session()->get('auth_version'),$this->details($r));return to_route('acceptance.show',$run)->with('status','Declared staging run created against the captured source/configuration. No checks passed automatically and no deployment occurred.');}
 public function show(Request $r,Run $run) {
  $this->manager($r);try{$details=$run->details;$checks=Check::where('run_id',$run->id)->get()->keyBy('scenario_id');$issues=Issue::where('run_id',$run->id)->orderBy('created_at')->orderBy('id')->get();$checkDetails=[];$issueDetails=[];foreach($checks as$c){$checkDetails[$c->id]=['details'=>$c->details,'note'=>$c->review_note];}foreach($issues as$i){$issueDetails[$i->id]=$i->details;}}catch(\Throwable){abort(409,'Run evidence cannot be verified. Reconcile the controlled records.');}
  $source=app(AcceptanceSource::class)->capture();return $this->privateView('show',['run'=>$run,'details'=>$details,'checks'=>$checks,'issues'=>$issues,'checkDetails'=>$checkDetails,'issueDetails'=>$issueDetails,'source'=>$source,'position'=>Acceptance::position($run,$source),'scenarios'=>Acceptance::scenarios($run),'people'=>User::where('active',true)->whereIn('role',['admin','ceo'])->get(['id','name']),'events'=>DB::table('staging_acceptance_events')->where('run_id',$run->id)->orderBy('id')->get(['event','record_version','actor_id','created_at'])]);
 }
 public function recordCheck(Request $r,Run $run,string $scenario) {
  $this->manager($r);$d=$r->validate(['version'=>['required','integer','min:0'],'outcome'=>['required','in:Passed,Failed,Blocked'],'tested_at'=>['required','date_format:Y-m-d H:i:s'],'reference'=>['required','string','max:1000'],'note'=>['required','string','max:2000'],'confirmed'=>['accepted']]);Acceptance::recordCheck($r->user(),(int)$r->session()->get('auth_version'),$run,$scenario,(int)$d['version'],$d);return back()->with('status','Actual observation recorded for independent checking. A failed/blocked observation remains a blocker even if its accuracy is accepted.');
 }
 public function reviewCheck(Request $r,Check $check) {
  $this->manager($r);$d=$r->validate(['version'=>['required','integer','min:1'],'decision'=>['required','in:accept,return'],'note'=>['required','string','max:2000'],'confirmed'=>['accepted']]);Acceptance::reviewCheck($r->user(),(int)$r->session()->get('auth_version'),$check,(int)$d['version'],$d['decision'],$d['note']);return back()->with('status','Independent observation decision recorded. This does not turn a Failed or Blocked result into Passed.');
 }
 private function issueData(Request $r):array {return $r->validate(['version'=>['required','integer','min:0'],'scenario_id'=>['nullable','string','max:64'],'severity'=>['required','in:Critical,Major,Minor'],'owner_id'=>['nullable','integer','min:1'],'due_on'=>['nullable','date_format:Y-m-d','after_or_equal:today'],'title'=>['required','string','max:160'],'detail'=>['required','string','max:4000'],'reference'=>['required','string','max:1000'],'confirmed'=>['accepted']]);}
 public function createIssue(Request $r,Run $run) {$this->manager($r);$d=$this->issueData($r);$i=Acceptance::saveIssue($r->user(),(int)$r->session()->get('auth_version'),$run,null,(int)$d['version'],$d);return to_route('acceptance.issue',$i)->with('status','Finding recorded. It blocks acceptance until independently resolved, or checked as a Minor deferral.');}
 public function issue(Request $r,Issue $issue) {
  $this->manager($r);$run=Run::findOrFail($issue->run_id);try{$details=$issue->details;$proposal=$issue->proposal;}catch(\Throwable){abort(409,'Finding evidence cannot be verified.');}return $this->privateView('issue',['issue'=>$issue,'run'=>$run,'details'=>$details,'proposal'=>$proposal,'position'=>Acceptance::position($run),'scenarios'=>Acceptance::scenarios($run),'people'=>User::where('active',true)->whereIn('role',['admin','ceo'])->get(['id','name'])]);
 }
 public function saveIssue(Request $r,Issue $issue) {$this->manager($r);$d=$this->issueData($r);Acceptance::saveIssue($r->user(),(int)$r->session()->get('auth_version'),Run::findOrFail($issue->run_id),$issue,(int)$d['version'],$d);return back()->with('status','Finding updated/reopened; earlier resolution proof is retained in history and no longer current.');}
 public function proposeIssue(Request $r,Issue $issue) {$this->manager($r);$d=$r->validate(['version'=>['required','integer','min:1'],'decision'=>['required','in:resolve,defer'],'reference'=>['required','string','max:1000'],'note'=>['required','string','max:2000'],'confirmed'=>['accepted']]);Acceptance::proposeIssue($r->user(),(int)$r->session()->get('auth_version'),$issue,(int)$d['version'],$d['decision'],$d['reference'],$d['note']);return back()->with('status','Resolution/Minor deferral proposed for a different administrator/CEO to check.');}
 public function reviewIssue(Request $r,Issue $issue) {$this->manager($r);$d=$r->validate(['version'=>['required','integer','min:1'],'decision'=>['required','in:accept,return'],'note'=>['required','string','max:2000'],'confirmed'=>['accepted']]);Acceptance::reviewIssue($r->user(),(int)$r->session()->get('auth_version'),$issue,(int)$d['version'],$d['decision'],$d['note']);return back()->with('status','Independent finding decision recorded. Critical/Major findings cannot be deferred.');}
 public function accept(Request $r,Run $run) {$this->manager($r);$d=$r->validate(['version'=>['required','integer','min:1'],'note'=>['required','string','max:2000'],'confirmed'=>['accepted']]);Acceptance::accept($r->user(),(int)$r->session()->get('auth_version'),$run,(int)$d['version'],$d['note']);return back()->with('status','Evidence accepted for the declared staging scope. No deployment, production approval or business completion was performed.');}
 public function reopen(Request $r,Run $run) {$this->manager($r);$d=$r->validate(['version'=>['required','integer','min:1'],'note'=>['required','string','max:2000'],'confirmed'=>['accepted']]);Acceptance::reopen($r->user(),(int)$r->session()->get('auth_version'),$run,(int)$d['version'],$d['note']);return back()->with('status','Run reopened. Earlier acceptance and check proofs are historical; record fresh observations for independent checking.');}
 public function fork(Request $r,Run $run) {$this->manager($r);$new=Acceptance::fork($r->user(),(int)$r->session()->get('auth_version'),$run,$this->details($r));return to_route('acceptance.show',$new)->with('status','New-source run created. Unresolved/deferred findings carried forward open; no test passes or acceptance carried forward.');}
 public function report(Request $r,Run $run) {
  $this->manager($r);$position=Acceptance::position($run);unset($position['evidence']);$checks=Check::where('run_id',$run->id)->get(['id','scenario_id','outcome','review_state','recorded_by','reviewed_by','tested_at','version']);$issues=Issue::where('run_id',$run->id)->get(['id','severity','state','owner_id','due_on','version']);
  try{$d=$run->details;$scope=collect($d)->only(['title','target','reference','programmes','exclusions','live_messaging'])->all();}catch(\Throwable){$scope=['status'=>'Cannot verify declared scope'];}
  return response()->json(['run_id'=>$run->id,'parent_run_id'=>$run->parent_id,'declarations_not_automatic_verification'=>$scope,'source_fingerprint'=>$run->source_hash,'position'=>$position,'checks'=>$checks,'findings'=>$issues,'private_notes_and_evidence_references_exported'=>false,'deployment_performed'=>false,'production_approved'=>false],200,['Content-Disposition'=>'attachment; filename="GTA-Scoped-Staging-Handover.json"','Cache-Control'=>'no-store, private','Referrer-Policy'=>'no-referrer']);
 }
}
